public abstract class Trabajo {

    // Atributos comunes, protected para que las hijas puedan usarlos

    protected String codigo;
    protected String estudio;
    protected String nombre;
    protected float horasEstimadas;
    protected boolean diurno;
    protected String estado;
    protected int contadorEjecuciones;
    protected boolean cobrado;


    // El constructor vacío que da mis valores default

    public Trabajo() {
        codigo = "";
        estudio = "";
        nombre = "";
        horasEstimadas = 0;
        diurno = true;
        estado = "En cola";
        contadorEjecuciones = 0;
        cobrado = false;
    }


    // Constructor nuevo, este ya modifica los valores

    public Trabajo(String codigo, String estudio, String nombre, float horasEstimadas, boolean diurno) {

        this.codigo = codigo;
        this.estudio = estudio;
        this.nombre = nombre;
        this.horasEstimadas = horasEstimadas;
        this.diurno = diurno;

        estado = "En cola";
        contadorEjecuciones = 0;
        cobrado = false;
    }


    // Seetters y Getters

    public void setCodigo(String newCodigo) {
        codigo = newCodigo;
    }

    public String getCodigo() {
        return codigo;
    }


    public void setEstudio(String newEstudio) {
        estudio = newEstudio;
    }

    public String getEstudio() {
        return estudio;
    }


    public void setNombre(String newNombre) {
        nombre = newNombre;
    }

    public String getNombre() {
        return nombre;
    }


    public void setHorasEstimadas(float newHoras) {
        horasEstimadas = newHoras;
    }

    public float getHorasEstimadas() {
        return horasEstimadas;
    }


    public void setDiurno(boolean newDiurno) {
        diurno = newDiurno;
    }

    public boolean getDiurno() {
        return diurno;
    }


    public void setEstado(String newEstado) {
        estado = newEstado;
    }

    public String getEstado() {
        return estado;
    }


    public void setContador(int newContador) {
        contadorEjecuciones = newContador;
    }

    public int getContador() {
        return contadorEjecuciones;
    }


    public void setCobrado(boolean newCobrado) {
        cobrado = newCobrado;
    }

    public boolean getCobrado() {
        return cobrado;
    }


    // Métodos abstractos que luego serán cambiados en cada subclase.
	// El costo es diferente por cada tipo, y por ello, necesita ser abstracto.
    public abstract float calcularCosto();

	//El tiempo de entrega cambia segun el tipo, y por ello, es abstracto.
    public abstract int tiempoEntrega();


    // Cantidades de intentos permitidos? Acá se obtiene esa pregunta.
    public abstract int maxIntentos();


    // Devuelve el nombre de la categoria del trabajo y para mantener la categoría
    public abstract String getCategoria();

	//Prácticamente solo sirve para la Simulacion física. Devolverá un true siempre, a menos que
		// Si y solo si (doble implicación, referencia) Sea una simulación física Y no tenga GPU
    public boolean compatNodo(Nodo nodo) {

        return true;
    }


    // Hace la ejecución, cambia el estado y aumenta el contador.

    public void iniciarEjecucion() {
        estado = "En ejecución";
        contadorEjecuciones++;
    }


    // Override del ToString, con algo que siempre está y luego solo le agrego más.

    @Override
    public String toString() {
        String horario;
        if (diurno) {
            horario = "Diurno";
        }
        else {
            horario = "Nocturno";
        }

        return "Categoría: " + getCategoria()
            + "\nCódigo: " + codigo
            + "\nEstudio: " + estudio
            + "\nProyecto: " + nombre
            + "\nHoras estimadas: " + horasEstimadas
            + "\nHorario: " + horario
            + "\nEstado: " + estado
            + "\nEjecuciones: " + contadorEjecuciones
            + "\nCobrado: " + cobrado;
    }
}
